            if(do_scaling) scale_row(row, width, fmt, processing_depth, &sb);

            if(apply_gamma) gamma_correct_row(row, width, fmt, gamma_lut);

            /* prev_scanline is always defiltered */
            memcpy(prev_scanline, scanline, scanline_width);

            if(interlaced)
